                    </button>
                    <button type="button" style={styles.closeButton} onClick={onClose}>
                        Cancel
                    </button>
                </form>

                {message && (
                    <div
                        style={{
                            marginTop: "15px",
                            color: message.type === "success" ? "#10b981" : "#ef4444",
                            fontWeight: "600",
                        }}
                    >
                        {message.text}
                    </div>
                )}
            </div>
        </div>
    );
}

